function u(string $escaped): string
{
    return json_decode('"' . $escaped . '"', true, 512, JSON_THROW_ON_ERROR);
}

function replace_once(string $content, string $search, string $replace, string $label): string
{
    $updated = str_replace($search, $replace, $content, $count);
    if ($count !== 1) {
        throw new RuntimeException("Replacement failed for {$label}: {$count}");
    }
    return $updated;
}

