(['automatic_sending_enabled' => true])->save();\n\n                Notification::make()\n                    ->success()\n                    ->title('" . u('\\u062a\\u0645 \\u062a\\u0634\\u063a\\u064a\\u0644 \\u0627\\u0644\\u0625\\u0631\\u0633\\u0627\\u0644 \\u0627\\u0644\\u062a\\u0644\\u0642\\u0627\\u0626\\u064a \\u0644\\u0647\\u0630\\u0627 \\u0627\\u0644\\u062d\\u0633\\u0627\\u0628\\u002e') . "')\n                    ->body('" . u('\\u0633\\u064a\\u062a\\u0645 \\u0625\\u0631\\u0633\\u0627\\u0644 \\u0627\\u0644\\u0631\\u0633\\u0627\\u0626\\u0644 \\u0628\\u0641\\u0627\\u0635\\u0644 \\u0639\\u0634\\u0648\\u0627\\u0626\\u064a \\u0645\\u0646 15 \\u0625\\u0644\\u0649 30 \\u062b\\u0627\\u0646\\u064a\\u0629\\u002e') . "')\n                    ->send();\n            });\n    }\n\n    public static function makeDisableAutomaticSendingAction(): Action\n    {\n        return Action::make('disable_automatic_sending')\n            ->label('" . u('\\u0625\\u064a\\u0642\\u0627\\u0641 \\u0627\\u0644\\u0625\\u0631\\u0633\\u0627\\u0644 \\u0627\\u0644\\u062a\\u0644\\u0642\\u0627\\u0626\\u064a') . "')\n            ->icon(Heroicon::OutlinedPause)\n            ->color('warning')\n            ->visible(fn (WhatsappAccount \\$record): bool => \\$record->automaticSendingEnabled())\n            ->requiresConfirmation()\n            ->modalDescription('" . u('\\u0633\\u064a\\u062a\\u0648\\u0642\\u0641 \\u0627\\u0644\\u0625\\u0631\\u0633\\u0627\\u0644 \\u0627\\u0644\\u062a\\u0644\\u0642\\u0627\\u0626\\u064a \\u0628\\u0639\\u062f \\u0627\\u0646\\u062a\\u0647\\u0627\\u0621 \\u0627\\u0644\\u0645\\u062d\\u0627\\u0648\\u0644\\u0629 \\u0627\\u0644\\u062d\\u0627\\u0644\\u064a\\u0629\\u060c \\u0648\\u0633\\u062a\\u0628\\u0642\\u0649 \\u0628\\u0642\\u064a\\u0629 \\u0627\\u0644\\u0631\\u0633\\u0627\\u0626\\u0644 \\u0645\\u0639\\u0644\\u0642\\u0629 \\u0644\\u0644\\u0625\\u0631\\u0633\\u0627\\u0644 \\u0627\\u0644\\u064a\\u062f\\u0648\\u064a \\u0623\\u0648 \\u0644\\u0644\\u062a\\u0634\\u063a\\u064a\\u06